function isHazard(obstacle: ObstacleDescriptor): obstacle is HazardObstacle {
  return obstacle.type === 'water' || obstacle.type === 'void' || obstacle.type === 'reset-zone';
}

/** Lightweight geometric ray/path estimate, deliberately not an omniscient physics trajectory. */
export function analyzePath(hole: Hole, start: Vec3, landing: Vec3, travelDistance: number): PathAnalysis {
  let hazardPenalty = 0;
  let obstacleHits = 0;
  for (const obstacle of hole.obstacles) {
    if (obstacle.enabled === false || !segmentHitsFootprint(start, landing, obstacle)) continue;
    if (isHazard(obstacle)) hazardPenalty += obstacle.penaltyStrokes ?? 1;
    else obstacleHits += 1;
  }
  const outOfBounds = landing.x < hole.bounds.min.x || landing.x > hole.bounds.max.x
    || landing.z < hole.bounds.min.z || landing.z > hole.bounds.max.z;
  return {
    outOfBounds,
    hazardPenalty,
    obstacleHits,
    estimatedTravelDistance: travelDistance,
    estimatedRemainingDistance: horizontalDistance(landing, hole.cup.position),
  };
}

function estimateScore(analysis: PathAnalysis, skill: BotSkill, random: RandomSource): number {
  const samples = Math.max(3, Math.round(skill.simulationSamples / 20));
  let simulatedRemaining = 0;
  for (let index = 0; index < samples; index += 1) {
    simulatedRemaining += Math.max(0, analysis.estimatedRemainingDistance * (1 + gaussian(random) * skill.powerError * 0.45));
  }
  const riskAversion = 1 - skill.riskTolerance;
  return simulatedRemaining / samples * 1.35
    + analysis.obstacleHits * (7 + riskAversion * 8)
    + analysis.hazardPenalty * (32 + riskAversion * 28)
    + (analysis.outOfBounds ? 70 + riskAversion * 30 : 0);
}

export function generateShotCandidates(hole: Hole, ballPosition: Vec3, skill: BotSkill, seed: number | string = 0): ShotCandidate[] {
  const random = createSeededRandom(seed);
  const targetAngle = Math.atan2(hole.cup.position.z - ballPosition.z, hole.cup.position.x - ballPosition.x);
  const targetDistance = horizontalDistance(ballPosition, hole.cup.position);
  const basePower = clamp((targetDistance - 1) / 12, 0.05, 0.98);
  const count = clamp(Math.round(skill.simulationSamples), MIN_CANDIDATES, MAX_CANDIDATES);
  const spread = 0.28 + (1 - skill.shortcutAwareness) * 0.32;
  const candidates: ShotCandidate[] = [];
  for (let index = 0; index < count; index += 1) {
    const ratio = count === 1 ? 0 : index / (count - 1);
    const offset = (ratio * 2 - 1) * spread;
    const powerOffset = (((index * 17) % count) / Math.max(1, count - 1) * 2 - 1) * 0.14;
    const normalizedPower = clamp(basePower + powerOffset, 0.04, 1);
    const direction = directionFromAngle(targetAngle + offset);
    const travelDistance = 1 + normalizedPower * 12;
    const landing = { x: ballPosition.x + direction.x * travelDistance, y: ballPosition.y, z: ballPosition.z + direction.z * travelDistance };
    const analysis = analyzePath(hole, ballPosition, landing, travelDistance);
    candidates.push({ direction, normalizedPower, landing, analysis, score: estimateScore(analysis, skill, random) });
  }
  return candidates.sort((left, right) => left.score - right.score);
}

export function planBotShot(profile: BotProfile, context: BotPlanningContext): BotPlan {
  const seed = context.seed ?? `${profile.id}:${context.hole.id}:${context.clientSequence}`;
  const random = createSeededRandom(seed);
  const candidates = generateShotCandidates(context.hole, context.ballPosition, profile.skill, seed);
  const selectionPool = Math.max(1, Math.min(candidates.length, 1 + Math.floor(profile.skill.riskTolerance * 8)));
  const selected = candidates[Math.floor(random() * selectionPool)] ?? candidates[0];
  if (!selected) throw new Error('Bot planner could not generate a shot candidate');
  const angle = Math.atan2(selected.direction.z, selected.direction.x) + gaussian(random) * profile.skill.aimError;
  const normalizedPower = clamp(selected.normalizedPower + gaussian(random) * profile.skill.powerError, 0.04, 1);
  return {
    candidates,
    chosenCandidate: selected,
    command: {
      playerId: context.playerId,
      holeId: context.hole.id,
      direction: directionFromAngle(angle),
      normalizedPower,
      clientSequence: context.clientSequence,
      issuedAt: context.issuedAt,
    },
  };
}
